/* Finnish Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Matti": "gift of God — Hebrew Mattityahu, via Matthew", "Maija": "The archetypal Finnish feminine name.", "Juho": "God is gracious — Hebrew Yohanan", "Aino": "the only one — Finnish, via the Kalevala", "Vaino": "A Kalevala name, short for Vainamoinen.", "Ilmari": "of the air — Finnish ilma (air), via Ilmarinen", "Korhonen": "The most common Finnish surname.", "Virtanen": "A classic nature surname.", "Makinen": "A classic nature surname.", "Nieminen": "A classic nature surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Matti';
console.log(lookup(q));

